from funcy import memoize
from funcy.calc import SkipMemoization

class MySkip(SkipMemoization):
    pass

raise_skip_called = [False]

@memoize
def memo_skip(x):
    if x == 'skip':
        raise MySkip()
    return x * 2

try:
    result = memo_skip('skip')
    print('Result:', result)
except MySkip as e:
    print('Caught MySkip:', e)
    raise_skip_called[0] = True
except Exception as e:
    print('Caught other:', type(e).__name__, e)

print('raise_skip_called:', raise_skip_called[0])
